def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    if not text:
        return []

    lines = text.splitlines(keepends=True)
    result = []
    current_line = []
    in_quoted_field = False
    field_start = 0

    # Helper function to add a field to the current line
    def add_field(start, end):
        nonlocal field_start
        if not in_quoted_field:
            field_content = text[field_start:end]
        else:
            # We need to unescape double quotes inside quoted fields
            field_content = text[field_start+1:end-1].replace('""', '"')
        current_line.append(field_content)
        field_start = end + 1

    i = 0
    while i < len(text):
        char = text[i]

        if not in_quoted_field and char == '"':
            # Check for escaped double quotes inside quoted fields.
            if i + 1 < len(text) and text[i+1] == '"':
                # If we have two consecutive quotes, it's an escaped quote
                i += 2
                continue
            else:
                # Start of a quoted field
                in_quoted_field = True
                field_start = i
        elif in_quoted_field and char == '"':
            if i + 1 < len(text) and text[i+1] == '"':
                # Escaped quote, skip the next one
                i += 2
                continue
            else:
                # End of quoted field
                in_quoted_field = False
        elif not in_quoted_field and char == delimiter:
            add_field(field_start, i)
        elif not in_quoted_field and (char == '\n' or (char == '\r' and i + 1 < len(text) and text[i+1] == '\n')):
            # End of line
            if i + 1 < len(text) and text[i+1] == '\n':
                add_field(field_start, i)
                i += 1  # Skip the newline character
            else:
                add_field(field_start, i)
            result.append(current_line)
            current_line = []
            field_start = i + 1
        elif in_quoted_field and char == '\n' or (in_quoted_field and char == '\r' and i + 1 < len(text) and text[i+1] == '\n'):
            # If we are inside a quoted field, treat line breaks as regular characters until it's closed
            pass

        i += 1

    if in_quoted_field:
        raise ValueError("Unterminated quote")

    # Handle the last field if not empty and not just whitespace or newline
    if field_start < len(text):
        add_field(field_start, len(text))

    # Add last line to result if it has content
    if current_line or (len(result) == 0 and field_start < len(text)):
        result.append(current_line)

    return result

